static void testCreativeEffects(const File& root,Assets& assets){
    expect(builtinEffectCount==8&&effectName(6)=="Delay"&&effectName(7)=="Distortion","eight stable effect identities expose Delay and Distortion");
    for(double rate:{8000.,44100.,48000.,96000.,192000.}){
        FiniteEcho delay;delay.prepare(rate);EchoSettings s;s.enabled=true;s.repeats=3;s.interval=20;s.fade=.5f;s.mix=1;delay.setSettings(s);int d=(int)std::round(rate*.02);bool taps=true,stereo=true,silent=true;
        for(int n=0;n<d*5;++n){float l=n==0?1.f:0.f,r=n==0?-.5f:0.f;delay.process(l,r);float expected=n==d?1:n==d*2?.5f:n==d*3?.25f:0;taps&=std::abs(l-expected)<1e-6f;stereo&=std::abs(r+expected*.5f)<1e-6f;if(n>d*3)silent&=l==0&&r==0;}
        expect(taps&&stereo&&silent,"finite Delay has exact repeat spacing, decay, stereo separation and no extra echoes across rates");
        delay.reset();s.fade=0;s.repeats=16;delay.setSettings(s);bool equal=true;for(int n=0;n<=d*17;++n){float l=n==0?1.f:0.f,r=0;delay.process(l,r);float expected=n>0&&n<=d*16&&n%d==0?1.f:0.f;equal&=l==expected&&r==0;}expect(equal,"zero-fade Delay keeps all sixteen repeats at equal level and then stops");
        s.fade=1;delay.setSettings(s);delay.reset();bool first=true;for(int n=0;n<d*4;++n){float l=n==0?1.f:0.f,r=0;delay.process(l,r);first&=l==(n==d?1.f:0.f);}expect(first,"100 percent fade leaves only the first repeat");
        s.enabled=false;delay.setSettings(s);float l=.123f,r=-.27f;delay.process(l,r);expect(l==.123f&&r==-.27f,"Delay bypass passes exact dry samples");
    }
    for(int mode=0;mode<3;++mode){GuitarDistortion distortion;distortion.prepare(48000);DistortionSettings s;s.enabled=true;s.mode=mode;s.drive=48;s.asymmetry=1;s.presence=12;s.cabinet=1;s.output=6;distortion.setSettings(s);bool finite=true;double energy=0,dc=0;for(int n=0;n<96000;++n){float l=.5f*(float)std::sin(2*MathConstants<double>::pi*220*n/48000),r=0;distortion.process(l,r);finite&=std::isfinite(l)&&std::isfinite(r)&&std::abs(l)<20&&r==0;energy+=l*l;if(n>48000)dc+=l;}expect(finite&&energy>1&&std::abs(dc/48000)<.02,"extreme tube/clip/fuzz settings stay finite, remove DC and keep stereo channels independent");distortion.reset();s.enabled=false;distortion.setSettings(s);float l=.123f,r=-.27f;distortion.process(l,r);expect(l==.123f&&r==-.27f,"Distortion bypass preserves exact samples");}
    for(int kind=0;kind<2;++kind){int count=kind?8:4;for(int i=0;i<count;++i){auto spec=kind?distortionSpecs()[(size_t)i]:echoSpecs()[(size_t)i];for(double normal:{0.,.25,.5,.75,1.}){double value=creativeValue(spec,normal);expect(value>=spec.low&&value<=spec.high&&(!spec.integer||value==std::round(value)),"effect parameter mapping respects bounds and discrete repeat counts");}for(const var& invalid:{var(true),var("4"),var(-99999.),var(999999.),var(std::numeric_limits<double>::infinity())}){auto json=kind?distortionToJson(DistortionSettings{}):echoToJson(EchoSettings{});json.getDynamicObject()->setProperty(spec.key,invalid);EchoSettings e;DistortionSettings d;expect((kind?distortionFromJson(json,d):echoFromJson(json,e)).failed(),"effect parameters reject booleans, text, infinity and out-of-range numbers");}}}
    auto p=emptyProject();p.loop=false;p.bpm=120;p.patterns[0].length=4;p.patterns[0].lanes[7]={{0,.25,48,.8f}};auto& m=p.tracks[7].mixer;m.delay={true,4,120,.3f,.4f};m.distortion.enabled=true;m.distortion.drive=32;m.distortion.mode=1;m.order={0,1,2,3,4,5,7,6};p.masterMixer.delay={true,2,170,.6f,.15f};
    auto file=root.getChildFile("creative-effects.pulse");Project read;expect(saveProject(p,file).wasOk()&&loadProject(file,read).wasOk()&&read.tracks[7].mixer.delay==m.delay&&read.tracks[7].mixer.distortion==m.distortion&&read.masterMixer.delay==p.masterMixer.delay&&read.tracks[7].mixer.order==m.order,"schema 28 retains both effects on channel and Master, including order");
    auto chain=captureEffectChain("Guitar echo",m);EffectChainPreset preset;expect(effectChainFromJson(effectChainToJson(chain),preset).wasOk()&&preset.settings.delay==m.delay&&preset.settings.distortion==m.distortion,"effect-chain schema 3 retains all new parameters");
    auto json=projectToJson(p);auto sentinel=JSON::toString(projectToJson(read));json["tracks"][7]["mixer"]["delay"].getDynamicObject()->setProperty("repeats",2.5);expect(projectFromJson(json,read).failed()&&JSON::toString(projectToJson(read))==sentinel,"fractional repeat counts fail atomically");
    json=projectToJson(emptyProject());json.getDynamicObject()->setProperty("schema",27);for(auto& t:*json["tracks"].getArray()){auto* obj=t["mixer"].getDynamicObject();obj->removeProperty("delay");obj->removeProperty("distortion");obj->setProperty("order",var(Array<var>{5,4,3,2,1,0}));}auto* settings=json["masterEffects"]["chain"]["settings"].getDynamicObject();settings->removeProperty("delay");settings->removeProperty("distortion");settings->setProperty("order",var(Array<var>{0,1,2,3,4,5}));json["masterEffects"]["chain"].getDynamicObject()->setProperty("schema",2);expect(projectFromJson(json,read).wasOk()&&read.tracks[7].mixer.order==EffectOrder{5,4,3,2,1,0,6,7}&&!read.tracks[7].mixer.delay.enabled&&!read.masterMixer.distortion.enabled,"real six-slot legacy projects append bypassed new effects without losing order");
    auto ops=JSON::parse(R"([{"op":"set_track","track":7,"effects":{"delay":{"repeats":5,"interval":200,"fade":0.2},"distortion":{"drive":28,"mode":2,"cabinet":0.8},"order":[0,1,2,3,4,5,7,6]}},{"op":"set_song","masterEffects":{"delay":{"mix":0.2}}}])");Project edited;expect(applyControlEdits(p,ops,edited).wasOk()&&edited.tracks[7].mixer.delay.repeats==5&&edited.tracks[7].mixer.distortion.mode==2&&edited.masterMixer.delay.enabled,"MCP supports partial new-effect edits on channels and Master");auto before=JSON::toString(projectToJson(edited));ops=JSON::parse(R"([{"op":"set_song","title":"Do not apply"},{"op":"set_track","track":7,"effects":{"distortion":{"tone":0}}}])");expect(applyControlEdits(p,ops,edited).failed()&&JSON::toString(projectToJson(edited))==before,"invalid effect batches reject without partial edits");
    auto audio=render(p,assets,root,96000,127),blocks=render(p,assets,root,96000,511);bool same=true;for(int c=0;c<2;++c)for(int n=0;n<96000;++n)same&=audio.getSample(c,n)==blocks.getSample(c,n)&&std::isfinite(audio.getSample(c,n));expect(same&&audio.getRMSLevel(0,0,96000)>.0001,"ordered channel/Master effects are audible and callback-size independent");
    RenderSettings format;format.bits=32;format.endBeat=4;format.tailSeconds=0;auto wav=root.getChildFile("guitar-delay.wav");expect(renderAudio(p,assets,root,wav,format).wasOk(),"new effects export as float WAV");String error;auto decoded=assets.load(wav,error);same=decoded&&decoded->audio.getNumSamples()==96000;if(same)for(int c=0;c<2;++c)for(int n=0;n<96000;++n)same&=std::abs(decoded->audio.getSample(c,n)-audio.getSample(c,n))<1e-6f;expect(same,"offline export matches callback effects sample for sample");
    auto first=audio;m.order={0,1,2,3,4,5,6,7};auto second=render(p,assets,root,96000,127);double difference=0;for(int n=0;n<96000;++n)difference+=std::abs(first.getSample(0,n)-second.getSample(0,n));expect(difference>1,"Distortion before/after Delay changes the actual rendered tone");
}
